public static StatusCode applyParameter(Supplier<StatusCode> applySupplier, Supplier<StatusCode> refreshSupplier,
                                        BooleanSupplier parameterCheckSupplier, String name, int deviceId) {
    if (FieldConstants.IS_SIMULATION) return applySupplier.get();
    for (int i = 1; i <= MAX_ATTEMPTS; i++) {
        applyStatus = applySupplier.get();
        refreshStatus = refreshSupplier.get();
        parameterCheck = parameterCheckSupplier.getAsBoolean();
        if (applyStatus.isOK() && refreshStatus.isOK() && parameterCheck) {
            if (i > 1) System.err.println("Successfully applied " + name + " to device " + deviceId + " on attempt " + i);
            return applyStatus;
        } else System.err.println("Failed to apply " + name + " to device " + deviceId + " on attempt " + i);
    }
    return applyStatus;
}

