public Command setSuperState(SuperState nextState) {
    return Commands.runOnce(() -> this.targetState = nextState).alongWith(
        Commands.parallel(fixArmAndClimb(nextState.armState, nextState.climbState),
                          setCoralClawState(nextState), setAlgaeClawState(nextState)));
}
public Command outtakeCommand() { return Commands.defer(() -> setSuperState(getPlacementState()), requirements); }

